(function(window,angular,undefined){"use strict";var mfb=angular.module("ng-mfb",[]);mfb.run(["$templateCache",function($templateCache){$templateCache.put("ng-mfb-menu-default.tpl.html",'<ul class="mfb-component--{{position}} mfb-{{effect}}"'+'    data-mfb-toggle="{{togglingMethod}}" data-mfb-state="{{menuState}}">'+'  <li class="mfb-component__wrap">'+'    <a ng-click="clicked()" ng-mouseenter="hovered()" ng-mouseleave="hovered()"'+'       ng-attr-data-mfb-label="{{label}}" class="mfb-component__button--main">'+'     <i class="mfb-component__main-icon--resting {{resting}}"></i>'+'     <i class="mfb-component__main-icon--active {{active}}"></i>'+"    </a>"+'    <ul class="mfb-component__list" ng-transclude>'+"    </ul>"+"</li>"+"</ul>");$templateCache.put("ng-mfb-menu-md.tpl.html",'<ul class="mfb-component--{{position}} mfb-{{effect}}"'+'    data-mfb-toggle="{{togglingMethod}}" data-mfb-state="{{menuState}}">'+'  <li class="mfb-component__wrap">'+'    <a ng-click="clicked()" ng-mouseenter="hovered()" ng-mouseleave="hovered()"'+'       style="background: transparent; box-shadow: none;"'+'       ng-attr-data-mfb-label="{{label}}" class="mfb-component__button--main">'+'     <md-button class="md-fab md-primary" aria-label={{label}} style="position:relative; margin: 0; padding:0;">'+'       <md-icon md-font-set="material-symbols-outlined"'+'         class="mfb-component__main-icon--resting">{{resting}}</md-icon>'+'       <md-icon md-font-set="material-symbols-outlined"'+'         class="mfb-component__main-icon--active">{{active}}</md-icon>'+"     </md-button>"+"    </a>"+'    <ul class="mfb-component__list" ng-transclude>'+"    </ul>"+"</li>"+"</ul>");$templateCache.put("ng-mfb-button-default.tpl.html","<li>"+'  <a data-mfb-label="{{label}}" class="mfb-component__button--child">'+'    <i class="mfb-component__child-icon {{icon}}">'+"    </i>"+"  </a>"+"</li>");$templateCache.put("ng-mfb-button-md.tpl.html","<li>"+'  <a href="" data-mfb-label="{{label}}" class="mfb-component__button--child" '+'     style="background: transparent; box-shadow: none;">'+'     <md-button style="margin: 0;" class="md-fab md-primary" aria-label={{label}}>'+'       <md-icon md-font-set="material-symbols-outlined">{{icon}}</md-icon>'+"     </md-button>"+"  </a>"+"</li>")}]);mfb.directive("mfbButtonClose",function(){return{restrict:"A",require:"^mfbMenu",link:function($scope,$element,$attrs,mfbMenuController){$element.bind("click",function(){mfbMenuController.close()})}}});mfb.directive("mfbMenu",["$timeout",function($timeout){return{restrict:"EA",transclude:true,replace:true,scope:{position:"@",effect:"@",label:"@",resting:"@restingIcon",active:"@activeIcon",mainAction:"&",menuState:"=?",togglingMethod:"@"},templateUrl:function(elem,attrs){return attrs.templateUrl||"ng-mfb-menu-default.tpl.html"},controller:["$scope","$attrs",function($scope,$attrs){var openState="open",closedState="closed";this.toggle=toggle;this.close=close;this.open=open;$scope.clicked=clicked;$scope.hovered=hovered;if(!$scope.menuState){$scope.menuState=closedState}if(_isTouchDevice()&&_isHoverActive()){$timeout(useClick)}$attrs.$observe("menuState",function(){$scope.currentState=$scope.menuState});function clicked(){if($scope.mainAction){$scope.mainAction()}if(!_isHoverActive()){toggle()}}function hovered(){if(_isHoverActive()){}}function toggle(){if($scope.menuState===openState){close()}else{open()}}function open(){$scope.menuState=openState}function close(){$scope.menuState=closedState}function _isTouchDevice(){return window.Modernizr&&Modernizr.touch}function _isHoverActive(){return $scope.togglingMethod==="hover"}function useClick(){$scope.$apply(function(){$scope.togglingMethod="click"})}}]}}]);mfb.directive("mfbButton",[function(){return{require:"^mfbMenu",restrict:"EA",transclude:true,replace:true,scope:{icon:"@",label:"@"},templateUrl:function(elem,attrs){return attrs.templateUrl||"ng-mfb-button-default.tpl.html"}}}])})(window,angular);